from __future__ import absolute_import, division, print_function,\
    unicode_literals
from builtins import range
from future import standard_library
import paramiko
from taf.ul.trs_e2e_fw.lib.call_utils.dongle.at import AT, DongleNotAttachedException
from taf.ul.trs_e2e_fw.lib.call_utils.dongle.cli_utils import Cli_Utils
from taf.ul.trs_e2e_fw.lib.call_utils.dongle.exceptions import DongleNotDetectedException, IPAddressNotAssigned
from taf.ul.trs_e2e_fw.lib.call_utils.exceptions import TEIDNotGeneratedException
from taf.ul.trs_e2e_fw.lib.call_utils.iperf.iperf import Iperf
from taf.ul.trs_e2e_fw.lib.call_utils.te_id import TeId
from taf.ul.trs_e2e_fw.lib.call_utils.ue import UE
from ute_common_store.store import Store
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger


standard_library.install_aliases()
logger = BackgroundLogger.Instance()


class Dongle(UE):
    """ This library provides keywords to control dongle. It currently supports Huawei dongle
    """
    def __init__(self, dut, macaddress, dongle_id, apn, interface_name,
                 iperf_remote_ip, rat, dongle_config_name):
        self.macaddress = macaddress
        self.rat = rat
        self.device_name = dongle_config_name
        product_id, device_id = dongle_id.split(':')
        self.te_id = TeId(dut, 'lte')
        ssh_session = self._ssh_to_dongle_host(rat, dongle_config_name)
        self.cli_utils_obj = Cli_Utils(ssh_session, macaddress, product_id,
                                       device_id, interface_name,
                                       iperf_remote_ip)
        self.at = AT(ssh_session, self.cli_utils_obj, rat, dongle_config_name, apn)
        self.store = Store()
        self.ue_type = "dongle"
        self.interface_name = interface_name

    def attach(self, verify_teid=False, call_type=None):
        logger.debug('Dongle Attach Called')
        max_attach_retries = 2
        for retry_attempt in range(max_attach_retries):
            logger.info('Attach Attempt :: {0}\n'.format(retry_attempt))
            # self.at.detach()
            if verify_teid:
                initial_iwf_value = self.te_id.get_te_id()
            try:
                self.ue_ip, self.gw_ip = self.at.attach()
                if verify_teid:
                    self.te_id.check_iwf_value_increased(initial_iwf_value)
                self.cli_utils_obj._reset_interface(self.interface_name)
                self.cli_utils_obj.add_route(self.ue_ip, self.gw_ip)
                return self.ue_ip
            except (DongleNotAttachedException, DongleNotDetectedException,
                    TEIDNotGeneratedException, IPAddressNotAssigned) as err:
                logger.info('Error message: {}'.format(err))
                if retry_attempt == max_attach_retries - 1:
                    raise err
                else:
                    continue

    def detach(self):
        self.at.detach()

    def call_start(self, call_type='data', device_section=None, profile=None, **kwargs):
        iperf = Iperf(self.ue_ip, device_section, profile, 'dongle', "lte", self.device_name)
        self.store.add(iperf, alias=profile)
        iperf.start_data(profile)

    def call_stop(self, call_type='data', profile=None):
        if call_type.lower() == 'data':
            iperf = self.store.get(alias=profile)
            throughput_fields = iperf.stop_data(profile)
            self.store.remove(alias=profile)
            return throughput_fields
            # self.cli_utils_obj.delete_route(self.gw_ip)
        else:
            logger.debug("Call type: {0} not supported. Dongle supports only"
                         " data. Doing nothing".format(call_type))

    def configure_ue(self, **kwargs):
        raise Exception('Configure UE operation not supported for Dongle yet')

    def call_teardown(self, **kwargs):
        pass

    def _ssh_to_dongle_host(self, rat, dongle_config_name):
        dongle_config_details = get_config_variable(["ue_devices", rat, dongle_config_name])
        remote_host = dongle_config_details.get('remote_ip', '127.0.0.1')
        remote_user = dongle_config_details.get('remote_user', 'ute')
        remote_pwd = dongle_config_details.get('remote_password', 'ute')
        tty_path = dongle_config_details.get('tty_path', '/dev/ttyUSB1')
        logger.debug("{0},{1},{2},{3}".format(remote_host, remote_user, remote_pwd, tty_path))
        ssh_session = paramiko.SSHClient()
        try:
            ssh_session.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh_session.connect(hostname=remote_host, username=remote_user, password=remote_pwd)
        except Exception as e:
            raise e
        return ssh_session


if __name__ == "__main__":
    pass
